$ErrorActionPreference='Stop'
$taskRoot=(Get-Location).Path
function TaskPin([string]$p) { if([IO.Path]::IsPathRooted($p)-or($p.Replace('\','/').Split('/')|Where-Object{$_-eq'..'})){throw 'pin path scope'};$v=Get-Item -LiteralPath $p;if($v.PSIsContainer-or($v.Attributes-band[IO.FileAttributes]::ReparsePoint)){throw 'pin file type'};[ordered]@{path=$p.Replace('\','/');bytes=$v.Length;sha256=(Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant()} }
$taskIndex=@{}
foreach($base in @('implementation/p09/source-archive','implementation/p09/source-archives')){if(Test-Path -LiteralPath $base){foreach($dir in Get-ChildItem -LiteralPath $base -Directory|Where-Object{$_.Name-match'^p09-(59|6[0-9]|7[0-8])[-]'}|Sort-Object Name){foreach($file in Get-ChildItem -LiteralPath $dir.FullName -File -Recurse|Sort-Object FullName){$path=$file.FullName.Substring($taskRoot.Length+1);$pin=TaskPin $path;$key="$($pin.bytes):$($pin.sha256)";if(-not$taskIndex.ContainsKey($key)){$taskIndex[$key]=$pin}}}}}
function MatchTaskPin($pin) { if(-not$pin.path-or-not$pin.sha256){throw 'pin shape'};if(Test-Path -LiteralPath $pin.path -PathType Leaf){$now=TaskPin $pin.path;if($now.bytes-eq$pin.bytes-and$now.sha256-eq$pin.sha256){return $now}};$key="$($pin.bytes):$($pin.sha256)";if($taskIndex.ContainsKey($key)){return $taskIndex[$key]};throw "whole original pin drift: $($pin.path)" }
$names=@('p09-59-full-document-form','p09-60-stored-full-ir','p09-61-authorized-ir','p09-62-postgres-revision','p09-63-revision-graph','p09-64-stored-full-document-request','p09-65-durable-full-request','p09-66-document-import-source','p09-67-document-import-structure','p09-68-document-import-forms','p09-69-document-import-form-policy','p09-70-stored-actual-form-import','p09-71-durable-actual-form-import','p09-72-document-import-fields','p09-73-document-import-field-semantics','p09-74-document-import-notes','p09-75-document-import-bookmarks','p09-76-document-import-style-catalog','p09-77-document-import-active-security')
$checked=0;$preserved=0
foreach($name in $names){$progress=Get-Content -LiteralPath ("implementation/p09/evidence/"+$name+".source-progress.v1.json") -Raw|ConvertFrom-Json;foreach($field in @('source_files','source_archives','predecessor_receipts')){if($progress.PSObject.Properties[$field]){foreach($pin in $progress.$field){$selected=MatchTaskPin $pin;$checked++;if($selected.path-ne$pin.path){$preserved++}}}}}
$p48=Get-Content -LiteralPath 'implementation/p09/evidence/p09-48-native-form-color-preparation.source-qualified.v1.json' -Raw|ConvertFrom-Json
$graphFiles=0;$graphBytes=0;$graphArchived=0
foreach($entry in $p48.complete_current_source_graph.source_sha256.PSObject.Properties){$graphFiles++;$selected=$null;if(Test-Path -LiteralPath $entry.Name -PathType Leaf){$now=TaskPin $entry.Name;if($now.sha256-eq$entry.Value){$selected=$now}};if(-not$selected){$selected=@($taskIndex.Values|Where-Object sha256 -EQ $entry.Value|Sort-Object path|Select-Object -First 1)[0];$graphArchived++};if(-not$selected){throw "original1551 drift: $($entry.Name)"};$graphBytes+=$selected.bytes}
$native=Get-Content -LiteralPath 'implementation/p09/evidence/p09-36-native-form-complete-recovery.r06.json' -Raw|ConvertFrom-Json;$nativeCount=0
foreach($entry in $native.native_evidence_sha256.PSObject.Properties){$now=TaskPin $entry.Name;if($now.sha256-ne$entry.Value){throw 'native evidence drift'};$nativeCount++}
$prior=Get-Content -LiteralPath 'implementation/p09/evidence/p09-77-document-import-active-security.source-progress.v1.json' -Raw|ConvertFrom-Json
$authorized=@('crates/hwpx-package/src/document_import/fields/semantics/catalog/security.rs','crates/product-cli/src/form_stored_provider/actual_import/field_ranges/semantics/catalog/security.rs','crates/product-cli/src/form_value_operation/full_document.rs','crates/product-cli/tests/form_stored_provider/actual_import.rs','PLANS.md')
$unchanged=0
foreach($pin in $prior.source_files){$path=if($authorized-contains$pin.path){'implementation/p09/source-archive/p09-78-pre-section-settings/'+$pin.path}else{$pin.path};$now=TaskPin $path;if($now.bytes-ne$pin.bytes-or$now.sha256-ne$pin.sha256){throw 'P77 source preservation drift'};if($authorized-notcontains$pin.path){$unchanged++}}
if($checked-ne4015-or$graphFiles-ne1551-or$graphBytes-ne51047472-or$nativeCount-ne75-or$unchanged-ne472){throw 'preservation counts drift'}
[ordered]@{predecessor_pin_entries=$checked;whole_original1551_files=$graphFiles;whole_original_bytes=$graphBytes;archived_graph_origins=$graphArchived;predecessor_changed_entries_whole_archived=$preserved;native_originals=$nativeCount;P77_unchanged_source_files=$unchanged;prechange_originals=5;all_hashes_exact=$true;entire_original_qualification_reexecuted=$false;hwp_process_count=@(Get-Process Hwp -ErrorAction SilentlyContinue).Count}|ConvertTo-Json -Compress
